class HashableMixin:
    def __hash__(self) -> int:
        return hash(
            tuple(
                [
                    getattr(self, k)
                    for k in sorted(vars(self).keys())
                    if not k.startswith("_")
                ]
            )
        )

    def __eq__(self, other) -> bool:
        self_keys = [k for k in vars(self).keys() if not k.startswith("_")]
        other_keys = [k for k in vars(other).keys() if not k.startswith("_")]

        same_keys = self_keys == other_keys
        if same_keys and isinstance(other, self.__class__):
            same_vals = all(
                map(lambda k: getattr(self, k) == getattr(other, k), self_keys)
            )
            return same_vals
        return False

import numpy as np

from fortuna.data.loader import DataLoader


def check_data_loader_is_not_random(data_loader: DataLoader) -> None:
    flag = False
    for (x1, y1), (x2, y2) in zip(data_loader, data_loader):
        if not np.alltrue(x1 == x2) or not np.alltrue(y1 == y2):
            flag = True
            break
    if flag:
        raise ValueError(
            """The data loader randomizes at every iteration. To perform this method, please provide a data loader that 
            generates the same sequence of data when called multiple times."""
        )

import logging
from typing import Type

import jax


def select_trainer_given_devices(
    devices: int,
    BaseTrainer: Type,
    JittedTrainer: Type,
    MultiDeviceTrainer: Type,
    disable_jit: bool,
) -> Type:
    if devices not in [0, -1]:
        raise NotImplementedError(
            "Currently, only two options are supported: use all available (`devices=-1`) or use only CPU (`devices=0`)."
        )
    elif devices == -1 and disable_jit:
        logging.warning("Jit must be enabled when not training on a single CPU device.")

    if devices == -1:
        logging.info("Training on all available devices.")
        trainer_cls = (
            MultiDeviceTrainer
            if len([d for d in jax.devices() if d.platform == "gpu"]) > 0
            else JittedTrainer
        )

    elif devices == 0 and disable_jit:
        logging.info("Training on CPU without jit.")
        trainer_cls = BaseTrainer
    else:
        logging.info("Training on CPU.")
        trainer_cls = JittedTrainer
    return trainer_cls

