        )
        self.assertIsInstance(optimizer, OmniOptimizer)
        self.assertEqual(len(optimizer.optimizer.param_groups), 4)

        expected_values = {
            0.2: {0.4: set([mini_net.fc1.weight]), 0.5: set([mini_net.fc1.bias])},
            0.3: {
