import betty.utils as utils


class DifferentiableOptimizerBase(torch.optim.Optimizer):
    def __init__(self, optimizer, module):
        self.param_groups = []
        self.state = [None for _ in range(len(list(module.parameters())))]
        self.param_mappings = []

        # initialize param_groups, state, param_mappings from unpatched module and optimizer.
        for init_param_group in optimizer.param_groups:
            param_group = {}
            for key, value in init_param_group.items():
                if key != "params":
                    param_group[key] = value

            param_mapping = []
            for param in init_param_group["params"]:
                param_idx = utils.get_param_index(param, module.parameters())
                param_mapping.append(param_idx)
                self.state[param_idx] = optimizer.state[param]

            self.param_groups.append(param_group)
            self.param_mappings.append(param_mapping)

    @abstractmethod
    def step(self, params):
        raise NotImplementedError

from betty.optim.optimizer import DifferentiableOptimizerBase


class DifferentiableSGD(DifferentiableOptimizerBase):
    """
    Differentiable version of PyTorch's
    `SGD <https://pytorch.org/docs/stable/generated/torch.optim.SGD.html#sgd>`_ optimizer.
    All in-place operations are replaced.
    """

    def step(self, params):
        for param_group, param_mapping in zip(self.param_groups, self.param_mappings):
            weight_decay = param_group["weight_decay"]
            momentum = param_group["momentum"]
            dampening = param_group["dampening"]
            nesterov = param_group["nesterov"]

            for param_idx in param_mapping:
                p = params[param_idx]

                if p.grad is None:
                    continue
                grad = p.grad
                if weight_decay != 0:
                    grad = grad + weight_decay * p

                param_state = self.state[param_idx]
                if (
                    "momentum_buffer" not in param_state
                    or param_state["momentum_buffer"] is None
                ):
                    buf = param_state["momentum_buffer"] = grad
                else:
                    buf = param_state["momentum_buffer"]
                    buf = momentum * buf + (1 - dampening) * grad
                    param_state["momentum_buffer"] = buf
                if nesterov:
                    grad = grad + momentum * buf
                else:
                    grad = buf

                p.update = param_group["lr"] * grad

        new_params = tuple(p - p.update for p in params if hasattr(p, "update"))
        for p in params:
            if hasattr(p, "update"):
                del p.update

        return new_params

