class COCOEvalCap:
    def __init__(self, coco, cocoRes):
        self.evalImgs = []
        self.eval = {}
        self.imgToEval = {}
        self.coco = coco
        self.cocoRes = cocoRes
        self.params = {"image_id": coco.getImgIds()}

    def evaluate(self):
        imgIds = self.params["image_id"]
        # imgIds = self.coco.getImgIds()
        gts = {}
        res = {}
        for imgId in imgIds:
            gts[imgId] = self.coco.imgToAnns[imgId]
            res[imgId] = self.cocoRes.imgToAnns[imgId]

        # =================================================
        # Set up scorers
        # =================================================
        print("tokenization...")
        tokenizer = PTBTokenizer()
        gts = tokenizer.tokenize(gts)
        res = tokenizer.tokenize(res)

        # =================================================
        # Set up scorers
        # =================================================
        print("setting up scorers...")
        scorers = [
            (Cider(), "CIDEr"),
        ]

        # =================================================
        # Compute scores
        # =================================================
        for scorer, method in scorers:
            print("computing %s score..." % (scorer.method()))
            score, scores = scorer.compute_score(gts, res)
            if type(method) == list:
                for sc, scs, m in zip(score, scores, method):
                    self.setEval(sc, m)
                    self.setImgToEvalImgs(scs, gts.keys(), m)
                    print("%s: %0.3f" % (m, sc))
            else:
                self.setEval(score, method)
                self.setImgToEvalImgs(scores, gts.keys(), method)
                print("%s: %0.3f" % (method, score))
        self.setEvalImgs()

    def setEval(self, score, method):
        self.eval[method] = score

    def setImgToEvalImgs(self, scores, imgIds, method):
        for imgId, score in zip(imgIds, scores):
            if not imgId in self.imgToEval:
                self.imgToEval[imgId] = {}
                self.imgToEval[imgId]["image_id"] = imgId
            self.imgToEval[imgId][method] = score

    def setEvalImgs(self):
        self.evalImgs = [eval for imgId, eval in self.imgToEval.items()]

from __future__ import annotations

from .types import (
    Any,
    Columns,
    LazyColumns,
    PandasDataFrame,
    PandasIndex,
    PandasRangeIndex,
)


def _check_type(argument: Any, against: type | set[type | None]) -> None:
    if isinstance(against, set):
        if len(against) == 0:
            against = {against}  # type: ignore
    if not isinstance(against, set):
        against = {against}
    optional = None in against
    just_types = against.difference({None})
    checks = [isinstance(argument, t) for t in just_types]  # type: ignore
    if optional:
        checks += [argument == None]
    if not any(checks):
        str_types = " | ".join([t.__name__ for t in just_types])  # type: ignore
        if optional:
            str_types += " | None"
        raise TypeError(f"must be {str_types}")


def _check_values(values: Any, type: type) -> None:
    if not all(isinstance(value, type) for value in values):
        raise TypeError(f"must be {type.__name__}")


def _check_keys(columns: LazyColumns | None, against: Columns | PandasIndex) -> None:
    if isinstance(columns, str):
        columns = [columns]
    columns = [] if (columns == None) else columns
    bad_keys = set(columns).difference(against)  # type: ignore
    if bad_keys:
        if len(bad_keys) == 1:
            raise KeyError(f"invalid key {bad_keys}")
        else:
            raise KeyError(f"invalid keys {bad_keys}")


def _check_index(df: PandasDataFrame) -> None:
    if not (df.index.name == None):
        raise IndexError("must be unnamed")
    if not isinstance(df.index, PandasRangeIndex):
        raise IndexError("must be range")
    if not (df.index.start == 0):
        raise IndexError("must start at 0")
    if not (df.index.step == 1):
        raise IndexError("must step by 1")


def _check_columns(df: PandasDataFrame) -> None:
    if type(df.columns) != PandasIndex:
        raise KeyError("must be flat")
    if df.columns.has_duplicates:
        raise KeyError("must not contain duplicate keys")


def _check_file(path: str) -> None:
    if not path.endswith(".csv"):
        raise TypeError("must end in .csv")

from __future__ import annotations

from ..checks import _check_type
from ..types import Direction, LazyColumns, PandasDataFrame, Value


def fill(
    df: PandasDataFrame,
    columns: LazyColumns | None = None,
    direction: Direction | None = None,
    constant: Value | None = None,
) -> PandasDataFrame:
    _check_type(columns, {list, str, None})
    _check_type(direction, {str, None})
    columns = [columns] if isinstance(columns, str) else columns
    if (direction != None) and (constant != None):
        raise ValueError("either direction OR constant must be None")
    if (direction == None) and (constant == None):
        raise ValueError("either direction OR constant must not be None")
    if direction != None:
        if not (direction in ["down", "up"]):
            raise ValueError("must be one of {'down', 'up'}")
        method = {"down": "ffill", "up": "bfill"}.get(direction)
        value = None
    if constant != None:
        value = constant
        method = None
    df = df.copy()
    if columns:
        df[columns] = df[columns].fillna(value=value, method=method)  # type: ignore
    else:
        df = df.fillna(value=value, method=method)  # type: ignore
    return df

from ..checks import _check_type
from ..types import Column, NewValue, OldValue, PandasDataFrame


def replace(
    df: PandasDataFrame, over: dict[Column, dict[OldValue, NewValue]]
) -> PandasDataFrame:
    _check_type(over, dict)
    bad_columns = list(set(over.keys()) - set(df.columns))
    if bad_columns and len(bad_columns) == 1:
        raise KeyError(f"column key: {bad_columns} is invalid")
    if bad_columns and len(bad_columns) > 1:
        raise KeyError(f"column keys: {bad_columns} are invalid")
    df = df.replace(over)
    return df

from __future__ import annotations

from ..checks import _check_type
from ..types import PandasDataFrame


def sample(
    df: PandasDataFrame, rows: int | float, seed: int | None = None
) -> PandasDataFrame:
    _check_type(rows, {int, float})
    if rows >= 1:
        if isinstance(rows, float):
            raise ValueError("must be int if > 1")
        df = df.sample(rows, random_state=seed)
    elif 0 < rows < 1:
        df = df.sample(frac=rows, random_state=seed)
    else:
        raise ValueError("must be > 0")
    df = df.reset_index(drop=True)
    return df

from __future__ import annotations

from ..checks import _check_type
from ..types import PandasDataFrame, PandasGroupedFrame


def take(
    df: PandasDataFrame | PandasGroupedFrame, rows: int = 1, **kwargs
) -> PandasDataFrame:
    if kwargs:  # compatibility: sklearn / train_test_split
        df = df.take(rows, **kwargs)  # type: ignore
        df = df.reset_index(drop=True)
        return df
    _check_type(rows, int)
    if isinstance(df, PandasDataFrame):
        if rows > df.shape[0]:
            raise ValueError("rows argument is invalid, exceeds total size")
    if rows == 0:
        raise ValueError("rows argument is invalid, must not be 0")
    if rows <= -1:
        df = df.tail(rows * -1)
    else:
        df = df.head(rows)
    if isinstance(df, PandasGroupedFrame):
        df = df.reset_index()
    else:
        df = df.reset_index(drop=True)
    return df

